ee:variables.ee:set-variable:
%dw 2.0
output application/java
---
{
	system: vars.remoteCall.system,
	service: {
		"type": "http",
		name: vars.remoteCall.service
	},
	operation: vars.remoteCall.operation default vars.operationContext.name,
	requestConfig: vars.remoteCall.requestConfig
}

set-variable.value:
#[output java import * from dw::util::Values var prefix = vars.requestConfig.micTransactionIdPrefix default "MLT" var txIdformat = "'" ++ prefix ++ "'yyyyMMddHHmmssSSSSSS"
fun calculateMicTransactionId() = (vars.requestConfig.micTransactionIdFormat default 'PREFIX_TIMESTAMP') match { case "UUID" -> uuid() case "PREFIX_UUID" -> prefix ++ uuid() else -> ((now() as String {format: txIdformat}) ++ "_" ++ randomInt(100)) }
fun update(operationContext) = do { var transactionId = vars.requestConfig.headers."mic_transaction_id" default operationContext.transactionId default (attributes.headers."mic_transaction_id" default calculateMicTransactionId())
var processId = vars.requestConfig.headers."mic_process_id" default operationContext.processId default attributes.headers."mic_process_id" default null --- ((operationContext default {}) -- ["processId", "transactionId"]) ++ { "processId": processId, "transactionId": transactionId } }
--- update(vars.operationContext)]

when.expression:
#[(
	(lower(vars.requestConfig."responseMode") default "sync") == "async"
) and 
(
	(vars.requestConfig.micTransactionIdFormat default 'PREFIX_TIMESTAMP') startsWith 'PREFIX_'

) and 
(
	!(
		vars.operationContext.transactionId startsWith (vars.requestConfig.micTransactionIdPrefix default "MLT")
	)
)]

ee:message.ee:set-payload:
%dw 2.0
output application/java

fun buildMessage(reason, message) = 
  if (!isEmpty(reason))
  	if (!isEmpty(message))
  	  reason ++ ": " ++ message
  	else reason	
  else if(!isEmpty(message))
    message
  else 'Unknown business error'
---
{
	code: payload.code,
	message: buildMessage(payload.reason, payload.message),
}

set-variable.value:
#[fun validate(path, value) =
{
	isValid: !isEmpty(value),
	path: path
}

fun consolidate(validations) = 
{
	isValid: isEmpty((validations default []) filter !$.isValid),
	invalidProperties: ((validations default []) filter !$.isValid).path joinBy ", "
}

---
consolidate([
	validate('remoteCall.system', vars.remoteCall.system),
	validate('remoteCall.service', vars.remoteCall.service.name),
	validate('operation (remoteCall.operation or operationContext.name)', vars.remoteCall.operation default vars.operationContext.name),		
])]

ee:variables.ee:set-variable:
%dw 2.0 output application/java
import * from modules::config::RemoteCallConfigUtils import * from modules::httpClient::HttpUtils
fun buildPath(basePath, resourcePath) = do {
fun cleanUp(path) = if (isEmpty(path)) path else path replace /\/+/ with '/'
var adjustedBasePath = basePath default '/' var absolutePath = if (isEmpty(resourcePath)) adjustedBasePath else adjustedBasePath ++ "/" ++ resourcePath --- cleanUp(absolutePath) }
fun buildUrl(protocol, host, port, path) = (protocol default 'https') ++ "://" ++ (host default '') ++ ":" ++ (port default '443') ++ path default ''
var protocol = getProperty(vars.remoteCall, 'protocol', 'https') var host = getProperty(vars.remoteCall, 'host', 'undefined') var port = getProperty(vars.remoteCall, 'port', '443') var basePath = getProperty(vars.remoteCall, 'basePath', '') var resourcePath = getProperty(vars.remoteCall, 'relativePath', '') var absolutePath = buildPath(basePath, resourcePath) var excludedRequestHeaders = getPropertyAsArray(vars.remoteCall, 'excludedRequestHeaders', ',', [])
--- { protocol: protocol, host: host, port: port, basePath: basePath, resourcePath: resourcePath, absolutePath: absolutePath, url: buildUrl(protocol, host, port, absolutePath), method: getProperty(vars.remoteCall, 'method', attributes.method), micTransactionIdFormat: getProperty(vars.remoteCall, 'micTransactionIdFormat', 'PREFIX_TIMESTAMP'), micTransactionIdPrefix: getProperty(vars.remoteCall, 'transactionIdPrefix', 'MLT'), micCorrelationIdField: getProperty(vars.remoteCall, 'correlationIdField', 'idCorrelationSpwA'), apiKey: getSecureProperty(vars.remoteCall, 'apiKey', 'undefined'), // convert to secure property after tests channel: getProperty(vars.remoteCall, 'channel', 'undefined'), // convert to secure property after tests isProxy: getProperty(vars.remoteCall, 'isProxy', vars.remoteCall.requestConfig.isProxy default false) as Boolean, excludedRequestHeaders: excludedRequestHeaders, excludedResponseHeaders: getPropertyAsArray(vars.remoteCall, 'excludedResponseHeaders', ',', []), responseTimeoutInMillis: getProperty(vars.remoteCall, 'responseTimeoutInMillis', 10000), responseMode: getProperty(vars.remoteCall, 'responseMode', 'sync'), transientErrors: getPropertyAsArray(vars.remoteCall, 'transientErrors', ',', []), transientStatusCodes: ((getPropertyAsArray(vars.remoteCall, 'transientStatusCodes', ',', ["408", "429", "502", "503", "504"])) map ($ as Number)), headers: removeHeaders(vars.remoteCall.requestConfig.headers default (attributes.headers default {}), excludedRequestHeaders), uriParams: vars.remoteCall.requestConfig.uriParams default (attributes.uriParams default {}), queryParams: vars.remoteCall.requestConfig.queryParams default (attributes.queryParams default {}), outboundTracking: { enabled: getProperty(vars.remoteCall, 'outboundTracking.enabled', lower(vars.remoteCall.system) != 'mic'), includeRequestPayload: getProperty(vars.remoteCall, 'outboundTracking.includeRequestPayload', true), includeResponsePayload: getProperty(vars.remoteCall, 'outboundTracking.includeResponsePayload', true) } }

%dw 2.0
output application/java
---
(vars.requestConfig default {} - "headers") 
++ {
	"headers":
		((vars.requestConfig.headers default {}) -- ["mic_process_id", "mic_transaction_id"]) ++ {
			"mic_api_key": vars.requestConfig.headers."mic_api_key" default vars.requestConfig.apiKey,
			"mic_channel": vars.requestConfig.headers."mic_channel" default vars.requestConfig.channel,
			"mic_process_id": vars.operationContext.processId,
			"mic_transaction_id": vars.operationContext.transactionId
		}
}

set-variable.value:
#[output java

import * from modules::httpClient::ObjectUtils

---
{
	payload: 
		if(vars.requestConfig.outboundTracking.includeRequestPayload default true)
			toString(payload, "request body not available")
		else "request payload omitted",
	timestamp: now()
}]

ee:message.ee:set-payload:
%dw 2.0
output application/java
---
{
	message: "An error occurred while calling the remote service"
}
